namespace RecipeSharing.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace RecipeSharing.Models;

public class SubmitRecipeModel
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be between 3 and 100 characters.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Ingredients are required.")]
    [MinLength(10, ErrorMessage = "Please provide more detail for ingredients.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Steps are required.")]
    [MinLength(10, ErrorMessage = "Please provide more detail for the steps.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeSharing.Models;

namespace RecipeSharing.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories = new List<RecipeCategory>
        {
            new() { Name = "Breakfast", Description = "Start your day with these morning favorites", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Quick and satisfying midday meals", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Hearty dishes for the whole family", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats to end any meal", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Light bites for any time of day", Icon = "🍿" },
            new() { Name = "Drinks", Description = "Refreshing beverages and smoothies", Icon = "🥤" }
        };

        _recipes = new List<Recipe>
        {
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Ingredients = "2 cups flour\n1 egg\n1 cup milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt",
                Steps = "1. Mix dry ingredients together.\n2. Whisk egg and milk, then combine with dry mix.\n3. Heat a skillet over medium heat and grease lightly.\n4. Pour batter and cook until bubbles form, then flip.\n5. Serve with maple syrup and fresh berries.",
                AverageRating = 4.5, RatingCount = 12
            },
            new()
            {
                Id = 2, Title = "Caesar Salad", Category = "Lunch",
                Ingredients = "1 head romaine lettuce\n1/2 cup croutons\n1/4 cup parmesan\nCaesar dressing\nGrilled chicken (optional)",
                Steps = "1. Wash and chop romaine lettuce.\n2. Toss with Caesar dressing.\n3. Top with croutons and shaved parmesan.\n4. Add grilled chicken if desired.",
                AverageRating = 4.2, RatingCount = 8
            },
            new()
            {
                Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
                Ingredients = "400g spaghetti\n500g ground beef\n1 can crushed tomatoes\n1 onion, diced\n3 cloves garlic\nOlive oil\nSalt and pepper\nFresh basil",
                Steps = "1. Cook spaghetti according to package directions.\n2. Sauté onion and garlic in olive oil.\n3. Brown the ground beef.\n4. Add tomatoes and simmer 20 minutes.\n5. Season and serve over pasta with fresh basil.",
                AverageRating = 4.8, RatingCount = 24
            },
            new()
            {
                Id = 4, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Ingredients = "2 1/4 cups flour\n1 cup butter\n3/4 cup sugar\n2 eggs\n1 tsp vanilla\n2 cups chocolate chips\n1 tsp baking soda",
                Steps = "1. Cream butter and sugar.\n2. Beat in eggs and vanilla.\n3. Mix in flour and baking soda.\n4. Fold in chocolate chips.\n5. Drop spoonfuls on baking sheet.\n6. Bake at 375°F for 9-11 minutes.",
                AverageRating = 4.9, RatingCount = 31
            },
            new()
            {
                Id = 5, Title = "Guacamole", Category = "Snacks",
                Ingredients = "3 ripe avocados\n1 lime, juiced\n1/2 tsp salt\n1/2 cup onion, diced\nCilantro\n2 tomatoes, diced\n1 tsp garlic",
                Steps = "1. Mash avocados in a bowl.\n2. Stir in lime juice and salt.\n3. Mix in onion, cilantro, tomatoes, and garlic.\n4. Serve immediately with tortilla chips.",
                AverageRating = 4.6, RatingCount = 15
            },
            new()
            {
                Id = 6, Title = "Berry Smoothie", Category = "Drinks",
                Ingredients = "1 cup mixed berries\n1 banana\n1 cup yogurt\n1/2 cup milk\n1 tbsp honey",
                Steps = "1. Add all ingredients to a blender.\n2. Blend until smooth.\n3. Pour into a glass and enjoy.",
                AverageRating = 4.3, RatingCount = 9
            }
        };
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(SubmitRecipeModel model)
    {
        var recipe = new Recipe
        {
            Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1,
            Title = model.Title,
            Category = model.Category,
            Ingredients = model.Ingredients,
            Steps = model.Steps,
            AverageRating = 0,
            RatingCount = 0
        };
        _recipes.Add(recipe);
    }

    public void RateRecipe(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
    }
}

