@page "/category/{CategoryName}"
@using RecipeSharing.Models
@using RecipeSharing.Services

<PageTitle>@CategoryName Recipes</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@_category?.Icon @CategoryName Recipes</h1>

    @if (_recipes.Count == 0)
    {
        <div class="alert alert-info mt-3">
            No recipes found in this category yet. <a href="/submit">Be the first to submit one!</a>
        </div>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-2 g-4 mt-2">
            @foreach (var recipe in _recipes)
            {
                <div class="col">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">
                                @if (recipe.RatingCount > 0)
                                {
                                    <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</span>
                                }
                                else
                                {
                                    <span>No ratings yet</span>
                                }
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] public required RecipeService RecipeService { get; set; }

    private List<Recipe> _recipes = new();
    private RecipeCategory? _category;

    protected override void OnParametersSet()
    {
        _category = RecipeService.GetCategories()
            .FirstOrDefault(c => c.Name.Equals(CategoryName, StringComparison.OrdinalIgnoreCase));
        _recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeSharing.Models
@using RecipeSharing.Services

<PageTitle>@(_recipe?.Title ?? "Recipe")</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (_recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@_recipe.Category.ToLower()">@_recipe.Category</a></li>
                <li class="breadcrumb-item active">@_recipe.Title</li>
            }
        </ol>
    </nav>

    @if (_recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1>@_recipe.Title</h1>
        <span class="badge bg-secondary mb-3">@_recipe.Category</span>

        <div class="row mt-3">
            <div class="col-md-4">
                <div class="card">
                    <div class="card-header"><strong>Ingredients</strong></div>
                    <div class="card-body">
                        <ul class="list-unstyled mb-0">
                            @foreach (var ingredient in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                            {
                                <li>• @ingredient</li>
                            }
                        </ul>
                    </div>
                </div>
            </div>
            <div class="col-md-8">
                <div class="card">
                    <div class="card-header"><strong>Instructions</strong></div>
                    <div class="card-body">
                        @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>

        <div class="card mt-4">
            <div class="card-body">
                <h5>Rate this Recipe</h5>
                <p class="text-muted mb-2">
                    @if (_recipe.RatingCount > 0)
                    {
                        <span>Average: ⭐ @_recipe.AverageRating.ToString("F1") (@_recipe.RatingCount ratings)</span>
                    }
                    else
                    {
                        <span>No ratings yet — be the first!</span>
                    }
                </p>
                <RecipeSharing.Components.Shared.StarRating RecipeId="@_recipe.Id" />
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }
    [Inject] public required RecipeService RecipeService { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetRecipeById(Id);
    }
}

@page "/submit"
@using RecipeSharing.Models
@using RecipeSharing.Services
@rendermode InteractiveServer

<PageTitle>Submit a Recipe</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit Your Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <strong>Thank you!</strong> Your recipe has been submitted successfully.
            <a href="/">Return to Home</a>
        </div>
    }
    else
    {
        <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="_model.Title" />
                <ValidationMessage For="() => _model.Title" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Name">@cat.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => _model.Category" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="5"
                    placeholder="One ingredient per line" @bind-Value="_model.Ingredients" />
                <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" class="form-control" rows="6"
                    placeholder="Describe each step" @bind-Value="_model.Steps" />
                <ValidationMessage For="() => _model.Steps" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-success">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    [Inject] public required RecipeService RecipeService { get; set; }

    private SubmitRecipeModel _model = new();
    private bool _submitted;

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(_model);
        _submitted = true;
    }
}

@using RecipeSharing.Services
@rendermode InteractiveServer

<div class="d-inline-block">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                @onclick="() => Rate(star)"
                title="Rate @star stars"
                style="cursor: pointer;">
            @(star <= _selectedRating ? "★" : "☆")
        </button>
    }
    @if (_rated)
    {
        <span class="ms-2 text-success fw-bold">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public required RecipeService RecipeService { get; set; }

    private int _selectedRating;
    private bool _rated;

    private void Rate(int stars)
    {
        _selectedRating = stars;
        RecipeService.RateRecipe(RecipeId, stars);
        _rated = true;
    }
}

